import React, { useState, useEffect, useCallback } from 'react';
import { Plus, X, Edit, Trash2, PinOff, Pin, Copy, List, Grid, Search } from 'lucide-react';

// Okay, so these are like, the app's main vibes (colors)
// Just copied 'em over from the main project, nbd.
const colors = {
  primary: '#ff3d7f',       // Vibrant pink - giving main character energy
  primaryLight: '#ff9db8',   // Lighter pink - for when we need a softer touch
  primaryDark: '#9c6172',    // Darker pink - mysterious, edgy
  secondary: '#121212',     // Deeper black - the void, but make it stylish
  secondaryLight: '#212121', // Light black - less void, more subtle backdrop
  light: '#ffffff',         // White - for when things gotta be crisp
  midGray: '#868686',       // Mid gray - kinda boring, but useful
  accent: '#00dbdd',        // Teal accent (cyan blue) - the pop of cool
  successGreen: '#4ADE80',  // Green for completed items - mission accomplished
  warningOrange: '#dc6300', // Orange for warnings - "uh oh, spaghettio"
  errorRed: '#FF3D3D'       // Red for errors/delete - this is serious business
};

// All the cool colors your notes can be!
// Wanted more options than just boring yellow, ya know?
const noteColors = [
  { bg: '#ffffff', border: '#e0e0e0', name: 'White' },
  { bg: '#f8f9c4', border: '#f0f283', name: 'Yellow' },
  { bg: '#c4f8e2', border: '#a7f0d1', name: 'Mint' },
  { bg: '#c4d4f8', border: '#a3baf0', name: 'Blue' },
  { bg: '#f8c4c4', border: '#f0a3a3', name: 'Pink' },
  { bg: '#e7c4f8', border: '#d5a3f0', name: 'Purple' },
  { bg: '#f8e1c4', border: '#f0d1a3', name: 'Orange' }
];

// Okay, so this is like, the *secret sauce* for making our scrollbars look pretty.
// Default ones are ugly, so we gotta get spicy with CSS.
const customScrollbarStyles = `
  .custom-scrollbar::-webkit-scrollbar {
    width: 8px;
    height: 8px;
  }
  
  .custom-scrollbar::-webkit-scrollbar-track {
    background: rgba(0, 0, 0, 0.2);
    border-radius: 10px;
  }
  
  .custom-scrollbar::-webkit-scrollbar-thumb {
    background: linear-gradient(to bottom, #ff3d7f, #00dbdd); /* Gradient for the win! */
    border-radius: 10px;
    border: 2px solid transparent; /* Keeps the gradient contained */
    background-clip: content-box;
  }
  
  .custom-scrollbar::-webkit-scrollbar-thumb:hover {
    background: linear-gradient(to bottom, #ff9db8, #00dbdd); /* Slightly different hover color, fancy! */
    background-clip: content-box;
  }
`;

const STORAGE_KEY = 'melodicJustice_stickyNotes'; // Storing notes under this key, pretty descriptive right?

const StickyNotes = ({ onUpdateNotes }) => {
  // All the state variables, tryin' to keep track of everything
  const [notes, setNotes] = useState([]); // Where all the notes live
  const [showAddModal, setShowAddModal] = useState(false); // Is the "add note" pop-up visible?
  const [currentNote, setCurrentNote] = useState({ // The note we're currently messing with (adding or editing)
    id: null,
    title: '',
    content: '',
    color: noteColors[0], // Default to white, 'cause why not?
    isPinned: false,
    createdAt: null,
    updatedAt: null
  });
  const [searchTerm, setSearchTerm] = useState(''); // What are we searching for?
  const [viewMode, setViewMode] = useState(() => {
    // Check localStorage first for view mode, otherwise grid is the default.
    // Gotta keep it consistent, even if you close the tab!
    return localStorage.getItem('melodicJustice_stickyNotes_viewMode') || 'grid';
  });
  const [showColorPicker, setShowColorPicker] = useState(false); // Is the color selector showing?
  const [isLoading, setIsLoading] = useState(true); // Are we still loading stuff from storage?

  // Saving notes to browser storage, gotta be careful if it's full though
  const saveNotesToStorage = useCallback((notesToSave) => {
    try {
      const dataToSave = JSON.stringify(notesToSave);
      localStorage.setItem(STORAGE_KEY, dataToSave);
      console.log(`Saved ${notesToSave.length} sticky notes to localStorage (flex).`);
      return true;
    } catch (error) {
      console.error('Failed to save notes, storage is probably full or something:', error);
      // If the user's storage is full, let 'em know they need to delete some stuff.
      if (error.name === 'QuotaExceededError') {
        alert('Uh oh, storage is full! Delete some notes or clear your browser data to make space.');
      }
      return false;
    }
  }, []); // Only re-create this function if dependencies change (none here, so it's stable)

  // Loading notes from browser storage, also need to handle errors
  const loadNotesFromStorage = useCallback(() => {
    try {
      const savedNotes = localStorage.getItem(STORAGE_KEY);
      if (savedNotes) {
        const parsedNotes = JSON.parse(savedNotes);
        // Just a quick check to make sure the loaded data isn't totally whack.
        if (Array.isArray(parsedNotes)) {
          const validNotes = parsedNotes.filter(note =>
            note &&
            typeof note === 'object' &&
            note.id &&
            note.content !== undefined
          );
          console.log(`Loaded ${validNotes.length} sticky notes from localStorage. We love consistency.`);
          return validNotes;
        }
      }
    } catch (error) {
      console.error('Failed to load notes, maybe the data got corrupted? Clearing it:', error);
      // If the data is messed up, better to just start fresh than have weird bugs.
      localStorage.removeItem(STORAGE_KEY);
    }
    return []; // No notes found or something went wrong, just return an empty array.
  }, []);

  // Effect to load notes when the component first shows up.
  // This runs once and sets the stage.
  useEffect(() => {
    setIsLoading(true); // Start loading animation (if we had one, haha)
    const loadedNotes = loadNotesFromStorage();
    setNotes(loadedNotes); // Put the loaded notes into our state
    setIsLoading(false); // Done loading, woo!
  }, [loadNotesFromStorage]); // This only runs if `loadNotesFromStorage` changes, which it won't.

  // Effect to save the view mode (grid or list) to localStorage.
  // Keeps your preference saved for next time.
  useEffect(() => {
    try {
      localStorage.setItem('melodicJustice_stickyNotes_viewMode', viewMode);
    } catch (error) {
      console.error('Failed to save view mode, classic localStorage issue:', error);
    }
  }, [viewMode]); // Runs every time `viewMode` changes.

  // Injecting custom scrollbar styles into the document head.
  // Because default scrollbars are a design crime.
  useEffect(() => {
    const styleElement = document.createElement('style');
    styleElement.innerHTML = customScrollbarStyles;
    document.head.appendChild(styleElement);

    // Cleanup function: remove the style when the component unmounts.
    // Gotta be tidy, you know?
    return () => {
      if (document.head.contains(styleElement)) {
        document.head.removeChild(styleElement);
      }
    };
  }, []); // Empty dependency array means this runs once on mount and cleans up on unmount.

  // Save notes to localStorage whenever they change, but with a slight delay.
  // This is called "debouncing" - prevents us from saving *too* often, like every keystroke.
  useEffect(() => {
    if (!isLoading && notes.length >= 0) { // Only save if we're not still loading and notes exist
      const timeoutId = setTimeout(() => {
        saveNotesToStorage(notes); // Actually save the notes
        if (onUpdateNotes) {
          onUpdateNotes(notes); // If there's a parent component listening, tell it about the update.
        }
      }, 500); // Wait 500ms before saving, just in case.

      return () => clearTimeout(timeoutId); // Cleanup: clear the timeout if notes change again before 500ms.
    }
  }, [notes, onUpdateNotes, saveNotesToStorage, isLoading]); // Runs when `notes` (or these other things) change.

  // Quick check for note validity. Don't want empty notes or super long ones.
  const validateNote = (note) => {
    if (!note.content || !note.content.trim()) {
      return { isValid: false, error: 'Seriously? A blank note? Try again.' };
    }
    if (note.content.length > 10000) {
      return { isValid: false, error: 'Woah, too much info! Note content is way too long (max 10,000 characters).' };
    }
    if (note.title && note.title.length > 200) {
      return { isValid: false, error: 'Title\'s a bit much, don\'t you think? (max 200 characters).' };
    }
    return { isValid: true };
  };

  // Opens the modal for adding a new note.
  const handleAddNote = () => {
    setCurrentNote({ // Reset the form fields for a fresh note
      id: null,
      title: '',
      content: '',
      color: noteColors[0],
      isPinned: false,
      createdAt: null,
      updatedAt: null
    });
    setShowAddModal(true); // Make the modal visible
    setShowColorPicker(false); // Hide the color picker, just in case
  };

  // Opens the modal to edit an existing note.
  const handleEditNote = (note) => {
    setCurrentNote({ ...note }); // Load the selected note's data into the form
    setShowAddModal(true); // Show the modal
    setShowColorPicker(false); // Again, hide the picker
  };

  // Saves a new note or updates an existing one. This is the big one.
  const handleSaveNote = () => {
    const validation = validateNote(currentNote);
    if (!validation.isValid) {
      alert(validation.error); // Pop up a warning if something's wrong
      return;
    }

    const now = new Date().toISOString(); // Get current timestamp, useful for tracking edits

    if (currentNote.id) {
      // If it has an ID, it's an existing note, so update it.
      const updatedNotes = notes.map(note =>
        note.id === currentNote.id
          ? { ...currentNote, updatedAt: now } // Update the note and its timestamp
          : note
      );
      setNotes(updatedNotes);
    } else {
      // No ID? Must be a new note!
      const newNote = {
        ...currentNote,
        id: `note_${Date.now()}_${Math.random().toString(36).substr(2, 9)}`, // Generate a unique ID (random, but works)
        createdAt: now,
        updatedAt: now
      };
      setNotes(prevNotes => [...prevNotes, newNote]); // Add it to the list!
    }

    setShowAddModal(false); // Close the modal after saving.
  };

  // Deletes a note after asking for confirmation.
  const handleDeleteNote = (id) => {
    // "Are you REALLY sure?" popup. Gotta be safe.
    if (window.confirm('For real though, are you sure you wanna delete this note? It\'s gone forever.')) {
      setNotes(prevNotes => prevNotes.filter(note => note.id !== id)); // Remove the note with the matching ID
    }
  };

  // Toggles the "pinned" status of a note. Pinned notes are VIPs.
  const handleTogglePin = (id) => {
    setNotes(prevNotes => prevNotes.map(note =>
      note.id === id
        ? { ...note, isPinned: !note.isPinned, updatedAt: new Date().toISOString() } // Flip the pin and update timestamp
        : note
    ));
  };

  // Makes a copy of a note. Useful for when you need to duplicate something quickly.
  const handleDuplicateNote = (note) => {
    const now = new Date().toISOString();
    const duplicatedNote = {
      ...note,
      id: `note_${Date.now()}_${Math.random().toString(36).substr(2, 9)}`, // New ID for the copy
      title: `${note.title} (Copy)`, // Add " (Copy)" to the title so you know
      isPinned: false, // Copies aren't pinned by default, just unpin them if you need to.
      createdAt: now,
      updatedAt: now
    };
    setNotes(prevNotes => [...prevNotes, duplicatedNote]); // Add the new copy to the list
  };

  // Wipes out ALL notes. This is the nuclear option, so confirm twice.
  const handleClearAllNotes = () => {
    if (window.confirm('ARE YOU ABSOLUTELY, POSITIVELY SURE you want to delete ALL sticky notes? This cannot be undone, for real.')) {
      setNotes([]); // Empty the notes array
      localStorage.removeItem(STORAGE_KEY); // Also clear them from browser storage
    }
  };

  // Exports all notes as a JSON file. Good for backups or sharing.
  const handleExportNotes = () => {
    try {
      const exportData = {
        notes: notes,
        exportDate: new Date().toISOString(),
        version: '1.0' // Just a little version number for future me
      };
      const dataStr = JSON.stringify(exportData, null, 2); // Make it pretty with indentation
      const dataBlob = new Blob([dataStr], { type: 'application/json' });
      const url = URL.createObjectURL(dataBlob);
      const link = document.createElement('a'); // Create a temporary download link
      link.href = url;
      link.download = `sticky-notes-backup-${new Date().toISOString().split('T')[0]}.json`; // Filename with date
      link.click(); // Click the link to trigger download
      URL.revokeObjectURL(url); // Clean up the temporary URL
    } catch (error) {
      console.error('Failed to export notes, rip:', error);
      alert('Export failed. Maybe try again?');
    }
  };

  // Formats dates to be human-readable. Because ISO strings are for robots.
  const formatDate = (dateString) => {
    try {
      const options = {
        year: 'numeric',
        month: 'short',
        day: 'numeric',
        hour: '2-digit',
        minute: '2-digit'
      };
      return new Date(dateString).toLocaleDateString(undefined, options); // Make it localized!
    } catch (error) {
      return 'Invalid date'; // Just in case the date is wonky
    }
  };

  // Filters notes based on the search term.
  const filteredNotes = notes.filter(note =>
    note.title.toLowerCase().includes(searchTerm.toLowerCase()) || // Check title
    note.content.toLowerCase().includes(searchTerm.toLowerCase()) // Check content
  );

  // Sorts notes: pinned ones first, then by the most recently updated.
  const sortedNotes = [...filteredNotes].sort((a, b) => {
    if (a.isPinned && !b.isPinned) return -1; // Pinned notes go first
    if (!a.isPinned && b.isPinned) return 1;
    return new Date(b.updatedAt) - new Date(a.updatedAt); // Then sort by most recent update
  });

  // Separate pinned and unpinned notes for easier rendering.
  const pinnedNotes = sortedNotes.filter(note => note.isPinned);
  const unpinnedNotes = sortedNotes.filter(note => !note.isPinned);

  // Show a loading message while we fetch notes.
  if (isLoading) {
    return (
      <div className="rounded-lg p-4 sticky-notes-container" style={{ backgroundColor: colors.secondary }}>
        <div className="text-center py-10">
          <div className="text-white">Loading sticky notes... please wait, the internet is slow today 😅</div>
        </div>
      </div>
    );
  }

  return (
    <div className="rounded-lg p-4 sticky-notes-container" style={{ backgroundColor: colors.secondary }}>
      {/* Header with search and view controls. The command center, basically. */}
      <div className="flex flex-wrap justify-between items-center mb-6">
        <div className="flex items-center w-full md:w-auto mb-3 md:mb-0">
          <div className="relative flex-grow mr-4 max-w-md">
            <div className="absolute inset-y-0 left-0 pl-3 flex items-center pointer-events-none">
              <Search className="w-5 h-5 text-gray-400" /> {/* Search icon, looking good */}
            </div>
            <input
              type="text"
              placeholder="Search notes... find your lost thoughts 🕵️‍♀️"
              className="w-full pl-10 pr-4 py-2 bg-gray-800 border border-gray-700 rounded-lg text-white focus:ring-2 focus:ring-cyan-500 focus:outline-none"
              value={searchTerm}
              onChange={(e) => setSearchTerm(e.target.value)}
            />
          </div>
          <div className="flex space-x-2">
            <button
              className={`p-2 rounded-lg transition-all ${viewMode === 'grid' ? 'bg-gray-700 shadow-inner' : 'bg-gray-800 hover:bg-gray-700'}`}
              onClick={() => setViewMode('grid')}
              title="Grid view (the classic look)"
            >
              <Grid className="w-5 h-5 text-white" />
            </button>
            <button
              className={`p-2 rounded-lg transition-all ${viewMode === 'list' ? 'bg-gray-700 shadow-inner' : 'bg-gray-800 hover:bg-gray-700'}`}
              onClick={() => setViewMode('list')}
              title="List view (for when you need to be organized AF)"
            >
              <List className="w-5 h-5 text-white" />
            </button>
          </div>
        </div>
        <div className="flex space-x-2">
          {notes.length > 0 && (
            <button
              className="px-3 py-2 rounded-lg text-white bg-red-600 hover:bg-red-700 transition-all"
              onClick={handleClearAllNotes}
              title="Clear all notes (if you dare 😈)"
            >
              Clear All
            </button>
          )}
          <button
            className="px-4 py-2 rounded-lg flex items-center space-x-2 text-white bg-gradient-to-r from-cyan-500 to-teal-500 hover:from-cyan-600 hover:to-teal-600 transition-all shadow-md hover:shadow-lg transform hover:scale-105"
            onClick={handleAddNote}
          >
            <Plus className="w-5 h-5" />
            <span>Add Note</span> {/* The magic button! */}
          </button>
        </div>
      </div>

      {/* Debug info, only visible when developing. For when things go sideways. */}
      {process.env.NODE_ENV === 'development' && (
        <div className="mb-4 p-2 bg-gray-800 rounded text-xs text-gray-400">
          Debug: {notes.length} notes loaded. Storage key: {STORAGE_KEY} (don't lose it!)
        </div>
      )}

      {/* Pinned Notes Section - These are the important ones! */}
      {pinnedNotes.length > 0 && (
        <div className="mb-6">
          <h3 className="text-gray-400 text-sm font-medium mb-3 border-b border-gray-800 pb-2">
            PINNED ({pinnedNotes.length})
          </h3>

          <div className={viewMode === 'grid'
            ? "grid grid-cols-1 sm:grid-cols-2 md:grid-cols-3 lg:grid-cols-4 gap-4"
            : "space-y-4"
          }>
            {pinnedNotes.map(note => (
              <div
                key={note.id}
                className={`rounded-lg p-4 relative transition-all hover:shadow-lg transform hover:scale-[1.02] cursor-pointer ${
                  viewMode === 'list' ? 'flex items-start min-h-40' : 'min-h-64'
                } group`} 
                style={{
                  backgroundColor: note.color.bg,
                  borderColor: note.color.border,
                  borderWidth: '1px',
                  borderStyle: 'solid'
                }}
                onClick={() => handleEditNote(note)}
              >
                {/* Note Content */}
                <div className={viewMode === 'list' ? 'flex-grow mr-4' : 'pb-8'}>
                  {note.title && (
                    <h3 className="font-bold mb-2 pr-6 break-words text-gray-900">
                      {note.title}
                    </h3>
                  )}
                  <div
                    className="whitespace-pre-wrap break-words text-gray-800 overflow-y-auto custom-scrollbar"
                    style={{
                      maxHeight: viewMode === 'list' ? '140px' : '180px',
                      minHeight: '80px'
                    }}
                  >
                    {note.content}
                  </div>

                  <div className="mt-3 text-xs text-gray-500">
                    Updated {formatDate(note.updatedAt)} (gotta stay fresh)
                  </div>
                </div>

                {/* Actions - these pop up on hover, slick! */}
                <div
                  className={`absolute ${viewMode === 'list' ? 'top-2 right-2 flex-col' : 'bottom-2 right-2 flex'} space-x-1 opacity-0 group-hover:opacity-100 transition-opacity`}
                  onClick={(e) => e.stopPropagation()} // Stop click from bubbling up to the note edit
                >
                  <button
                    className="p-1 text-gray-700 hover:text-gray-900 transition-colors bg-white bg-opacity-80 rounded"
                    onClick={(e) => {
                      e.stopPropagation();
                      handleTogglePin(note.id);
                    }}
                    title="Unpin (free it!)"
                  >
                    <Pin className="w-4 h-4" /> {/* Switched to Pin for unpin action when pinned */}
                  </button>
                  <button
                    className="p-1 text-gray-700 hover:text-gray-900 transition-colors bg-white bg-opacity-80 rounded"
                    onClick={(e) => {
                      e.stopPropagation();
                      handleEditNote(note);
                    }}
                    title="Edit (make changes)"
                  >
                    <Edit className="w-4 h-4" />
                  </button>
                  <button
                    className="p-1 text-gray-700 hover:text-gray-900 transition-colors bg-white bg-opacity-80 rounded"
                    onClick={(e) => {
                      e.stopPropagation();
                      handleDuplicateNote(note);
                    }}
                    title="Duplicate (copy-paste, but cooler)"
                  >
                    <Copy className="w-4 h-4" />
                  </button>
                  <button
                    className="p-1 text-gray-700 hover:text-red-600 transition-colors bg-white bg-opacity-80 rounded"
                    onClick={(e) => {
                      e.stopPropagation();
                      handleDeleteNote(note.id);
                    }}
                    title="Delete (adios note)"
                  >
                    <Trash2 className="w-4 h-4" />
                  </button>
                </div>
              </div>
            ))}
          </div>
        </div>
      )}

      {/* Other Notes Section - the regular ones */}
      <div>
        {pinnedNotes.length > 0 && unpinnedNotes.length > 0 && (
          <h3 className="text-gray-400 text-sm font-medium mb-3 border-b border-gray-800 pb-2">
            OTHERS ({unpinnedNotes.length})
          </h3>
        )}

        {unpinnedNotes.length > 0 ? (
          <div className={viewMode === 'grid'
            ? "grid grid-cols-1 sm:grid-cols-2 md:grid-cols-3 lg:grid-cols-4 gap-4"
            : "space-y-4"
          }>
            {unpinnedNotes.map(note => (
              <div
                key={note.id}
                className={`rounded-lg p-4 relative transition-all hover:shadow-lg transform hover:scale-[1.02] cursor-pointer group ${
                  viewMode === 'list' ? 'flex items-start min-h-40' : 'min-h-64'
                }`}
                style={{
                  backgroundColor: note.color.bg,
                  borderColor: note.color.border,
                  borderWidth: '1px',
                  borderStyle: 'solid'
                }}
                onClick={() => handleEditNote(note)}
              >
                {/* Note Content */}
                <div className={viewMode === 'list' ? 'flex-grow mr-4' : 'pb-8'}>
                  {note.title && (
                    <h3 className="font-bold mb-2 pr-6 break-words text-gray-900">
                      {note.title}
                    </h3>
                  )}
                  <div
                    className="whitespace-pre-wrap break-words text-gray-800 overflow-y-auto custom-scrollbar"
                    style={{
                      maxHeight: viewMode === 'list' ? '140px' : '180px',
                      minHeight: '80px'
                    }}
                  >
                    {note.content}
                  </div>

                  <div className="mt-3 text-xs text-gray-500">
                    Updated {formatDate(note.updatedAt)}
                  </div>
                </div>

                {/* Actions */}
                <div
                  className={`absolute ${viewMode === 'list' ? 'top-2 right-2 flex-col' : 'bottom-2 right-2 flex'} space-x-1 opacity-0 group-hover:opacity-100 transition-opacity`}
                  onClick={(e) => e.stopPropagation()}
                >
                  <button
                    className="p-1 text-gray-700 hover:text-gray-900 transition-colors bg-white bg-opacity-80 rounded"
                    onClick={(e) => {
                      e.stopPropagation();
                      handleTogglePin(note.id);
                    }}
                    title="Pin (make it stick!)"
                  >
                    <PinOff className="w-4 h-4" /> {/* Switched to PinOff for pin action when unpinned */}
                  </button>
                  <button
                    className="p-1 text-gray-700 hover:text-gray-900 transition-colors bg-white bg-opacity-80 rounded"
                    onClick={(e) => {
                      e.stopPropagation();
                      handleEditNote(note);
                    }}
                    title="Edit (fix those typos)"
                  >
                    <Edit className="w-4 h-4" />
                  </button>
                  <button
                    className="p-1 text-gray-700 hover:text-gray-900 transition-colors bg-white bg-opacity-80 rounded"
                    onClick={(e) => {
                      e.stopPropagation();
                      handleDuplicateNote(note);
                    }}
                    title="Duplicate (just because)"
                  >
                    <Copy className="w-4 h-4" />
                  </button>
                  <button
                    className="p-1 text-gray-700 hover:text-red-600 transition-colors bg-white bg-opacity-80 rounded"
                    onClick={(e) => {
                      e.stopPropagation();
                      handleDeleteNote(note.id);
                    }}
                    title="Delete (bye bye)"
                  >
                    <Trash2 className="w-4 h-4" />
                  </button>
                </div>
              </div>
            ))}
          </div>
        ) : (
          sortedNotes.length === 0 && (
            <div className="text-center py-10 bg-gray-800 rounded-lg">
              <p className="text-gray-400">
                {searchTerm ? 'No notes match your search. Guess it\'s time to get creative 🤷‍♀️' : 'No notes yet. Click "Add Note" to create one. Your thoughts deserve a home!'}
              </p>
            </div>
          )
        )}
      </div>

      {/* Add/Edit Note Modal - The big pop-up for creating/changing notes */}
      {showAddModal && (
        <div className="fixed inset-0 bg-black bg-opacity-75 backdrop-blur-sm flex items-center justify-center z-50">
          <div
            className="bg-gray-900 rounded-lg shadow-2xl max-w-2xl w-full max-h-[90vh] flex flex-col border border-gray-700"
          >
            <div className="flex justify-between items-center p-4 border-b border-gray-800">
              <h3 className="text-xl font-bold text-white">
                {currentNote.id ? 'Edit Note' : 'Add Note'} {/* Title changes based on action */}
              </h3>
              <button
                className="text-gray-400 hover:text-white transition-colors"
                onClick={() => setShowAddModal(false)}
              >
                <X className="w-6 h-6" /> {/* Close button, simple X */}
              </button>
            </div>

            <div className="p-4 flex-grow overflow-y-auto custom-scrollbar">
              <div className="mb-4">
                <input
                  type="text"
                  placeholder="Title (optional) - make it catchy!"
                  className="w-full px-4 py-2 bg-gray-800 border border-gray-700 rounded-lg text-white mb-4 focus:ring-2 focus:ring-cyan-500 focus:outline-none"
                  value={currentNote.title}
                  maxLength={200}
                  onChange={(e) => setCurrentNote({ ...currentNote, title: e.target.value })}
                />

                <textarea
                  placeholder="Note content... spill the tea ☕"
                  className="w-full px-4 py-2 bg-gray-800 border border-gray-700 rounded-lg text-white h-64 resize-none focus:ring-2 focus:ring-cyan-500 focus:outline-none"
                  value={currentNote.content}
                  maxLength={10000}
                  onChange={(e) => setCurrentNote({ ...currentNote, content: e.target.value })}
                />
                <div className="text-xs text-gray-400 mt-1">
                  {currentNote.content.length}/10,000 characters (don't write a novel)
                </div>
              </div>

              <div className="flex items-center justify-between mt-4">
                <div className="flex items-center space-x-4">
                  {/* Note Color Button - click to change the note's aesthetic */}
                  <div className="relative">
                    <button
                      className="px-3 py-2 rounded-lg flex items-center space-x-2 bg-gray-800 text-white border border-gray-700 hover:bg-gray-700 transition-all"
                      onClick={() => setShowColorPicker(!showColorPicker)}
                    >
                      <div
                        className="w-4 h-4 rounded-full border border-gray-500"
                        style={{ backgroundColor: currentNote.color.bg }}
                      />
                      <span>Note Color</span>
                    </button>

                    {/* Color Picker - this pops out next to the button */}
                    {showColorPicker && (
                      <div className="absolute top-0 left-full ml-2 p-3 bg-gray-800 rounded-lg shadow-xl z-20 border border-gray-700" style={{ minWidth: '320px' }}>
                        <div className="flex gap-2">
                          {noteColors.map((color, index) => (
                            <button
                              key={index}
                              className={`w-8 h-8 rounded-full border-2 transition-all hover:scale-110 flex-shrink-0 ${
                                currentNote.color === color
                                  ? 'border-cyan-400 ring-2 ring-cyan-400 ring-opacity-50' // Highlight selected color
                                  : 'border-gray-600 hover:border-gray-400'
                              }`}
                              style={{ backgroundColor: color.bg }}
                              onClick={() => {
                                setCurrentNote({ ...currentNote, color });
                                setShowColorPicker(false); // Close picker after selection
                              }}
                              title={color.name}
                            />
                          ))}
                        </div>
                      </div>
                    )}
                  </div>
                </div>

                <div className="flex items-center space-x-2">
                  <button
                    className={`flex items-center space-x-1 px-3 py-2 rounded-lg transition-all ${
                      currentNote.isPinned
                        ? 'bg-pink-600 hover:bg-pink-700 text-white' // Pinned style
                        : 'bg-gray-800 hover:bg-gray-700 text-white border border-gray-700' // Unpinned style
                    }`}
                    onClick={() => setCurrentNote({ ...currentNote, isPinned: !currentNote.isPinned })}
                  >
                    {currentNote.isPinned ? (
                      <>
                        <Pin className="w-4 h-4" />
                        <span>Pinned (can't lose this!)</span>
                      </>
                    ) : (
                      <>
                        <PinOff className="w-4 h-4" />
                        <span>Pin (for priority)</span>
                      </>
                    )}
                  </button>

                  {currentNote.id && ( // Only show delete button if it's an existing note
                    <button
                      className="px-3 py-2 bg-red-600 hover:bg-red-700 text-white rounded-lg transition-all"
                      onClick={() => {
                        if (window.confirm('Delete this note for good? You sure?')) {
                          handleDeleteNote(currentNote.id);
                          setShowAddModal(false); // Close modal after deleting
                        }
                      }}
                    >
                      Delete
                    </button>
                  )}
                </div>
              </div>
            </div>

            <div className="flex justify-end p-4 border-t border-gray-800">
              <button
                className="px-4 py-2 mr-2 bg-gray-700 hover:bg-gray-600 text-white rounded-lg transition-all"
                onClick={() => setShowAddModal(false)}
              >
                Cancel (changed my mind)
              </button>
              <button
                className="px-4 py-2 rounded-lg text-white bg-gradient-to-r from-cyan-500 to-teal-500 hover:from-cyan-600 hover:to-teal-600 transition-all shadow-md hover:shadow-lg transform hover:scale-105 disabled:opacity-50 disabled:cursor-not-allowed disabled:transform-none"
                onClick={handleSaveNote}
                disabled={!currentNote.content.trim()} // Can't save an empty note, duh
              >
                Save
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default StickyNotes; // Export so other parts of the app can use this!
